export const W=960,H=540,GRAVITY=420;
export const weapons={shell:{name:'Granat',radius:42,damage:54,cost:0},heavy:{name:'Tung granat',radius:64,damage:72,cost:250},cluster:{name:'Klynge',radius:48,damage:42,cost:400}};
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),r3=n=>Math.round(n*1000)/1000,groundAt=(g,x)=>g[clamp(Math.round(x),0,W-1)];
export function terrain(seed){let s=seed>>>0;const random=()=>((s=(Math.imul(s,1664525)+1013904223)>>>0)/4294967296);const phase=random()*6.28;return Array.from({length:W},(_,x)=>Math.round(391+34*Math.sin(x/96+phase)+22*Math.sin(x/41+phase*1.7)+12*Math.sin(x/19+phase*.7)));}
export function materialAt(seed,round,x){const phase=((seed>>>0)%997)/997*6.28+round*.37;const ridge=Math.sin(x/88+phase)+.38*Math.sin(x/31-phase*1.3);return ridge>.48?'rock':'grass';}
function tank(name,x,g){return {name,x,y:groundAt(g,x)-15,vx:0,vy:0,rotation:0,angularVelocity:0,hp:100,cash:500,score:0,kills:0,angle:48,power:66};}
export function newGame({seed=Math.floor(Math.random()*2**32),mode='standard',names=['Du','Computer']}={}){const ground=terrain(seed);return {seed,mode,ground,wind:Math.round(((seed%19)-9)*.8),turn:0,round:1,maxRounds:5,shots:0,players:[tank(names[0],105,ground),tank(names[1],855,ground)],roundStartScores:[0,0],last:null,winner:null};}
export function aimDirection(state,player){return state.players[1-player].x>=state.players[player].x?1:-1;}
export function trace(state,player,angle,power){const p=state.players[player],dir=aimDirection(state,player),r=angle*Math.PI/180,speed=power*5.25;let x=p.x+dir*48*Math.cos(r),y=p.y-17-48*Math.sin(r),vx=dir*speed*Math.cos(r),vy=-speed*Math.sin(r);const path=[];for(let i=0;i<1500;i++){x+=vx/60;y+=vy/60;vx+=state.wind*3.2/60;vy+=GRAVITY/60;if(i%3===0)path.push([r3(x),r3(y),r3(Math.atan2(vy,vx))]);if(x<0||x>=W||y>H+100)return {x:clamp(x,0,W-1),y:clamp(y,0,H),path,miss:true};const target=state.players[1-player];if(Math.hypot(x-target.x,y-target.y)<17)return {x:r3(x),y:r3(y),path,miss:false,direct:true};if(y>=groundAt(state.ground,x))return {x:r3(x),y:groundAt(state.ground,x),path,miss:false};}return {x:r3(x),y:r3(y),path,miss:true};}
const support=(g,x)=>{const left=groundAt(g,x-15),right=groundAt(g,x+15);return {y:(left+right)/2-15,slope:Math.atan2(right-left,30)};};
export function settleTanks(state){const frames=[];for(let step=0;step<300;step++){let active=false;for(const p of state.players){const dt=1/60,s=support(state.ground,p.x),contact=p.y>=s.y-1&&p.vy>=-5;if(contact){p.y=s.y;p.vy=0;p.vx+=GRAVITY*Math.sin(s.slope)*dt*.43;p.vx*=.91;if(Math.abs(p.vx)<.045)p.vx=0;const difference=Math.atan2(Math.sin(s.slope-p.rotation),Math.cos(s.slope-p.rotation));p.angularVelocity+=difference*.19+(p.vx*dt/18)*.35;p.angularVelocity*=.70;}else{p.vy+=GRAVITY*dt;p.angularVelocity*=.992;}p.x=clamp(p.x+p.vx*dt,22,W-23);p.y+=p.vy*dt;p.rotation+=p.angularVelocity;const next=support(state.ground,p.x);if(p.y>next.y){const impact=Math.max(0,p.vy);p.y=next.y;p.vy=0;if(impact>210)p.hp=Math.max(0,p.hp-Math.round((impact-210)/18));}if(Math.abs(p.vx)>.05||Math.abs(p.vy)>.05||Math.abs(p.angularVelocity)>.002||Math.abs(Math.atan2(Math.sin(s.slope-p.rotation),Math.cos(s.slope-p.rotation)))>.012)active=true;}if(step%4===0)frames.push(state.players.map(p=>({x:r3(p.x),y:r3(p.y),rotation:r3(p.rotation)})));if(!active&&step>15)break;}for(const p of state.players){p.x=r3(p.x);p.y=r3(p.y);p.vx=r3(p.vx);p.vy=r3(p.vy);p.rotation=r3(p.rotation);p.angularVelocity=r3(p.angularVelocity);}return frames;}
function carve(g,x,y,r,seed,round){for(let i=Math.max(0,Math.floor(x-r));i<Math.min(W,Math.ceil(x+r));i++){const d=Math.abs(i-x),depth=Math.sqrt(Math.max(0,r*r-d*d)),target=clamp(Math.round(y+depth*.9),0,H-14),resistance=materialAt(seed,round,i)==='rock'?.38:1;g[i]=Math.round(g[i]+Math.max(0,target-g[i])*resistance);}}
export function fire(state,{angle,power,weapon='shell'}={}){if(state.winner!==null)throw Error('Kampen er slut');if(!Number.isInteger(angle)||angle<5||angle>85||!Number.isInteger(power)||power<10||power>100||!weapons[weapon])throw Error('Ugyldigt skud');const actor=state.turn,p=state.players[actor],w=weapons[weapon],beforeRound=state.round,windBefore=state.wind;if(p.cash<w.cost)throw Error('Ikke nok kredit');p.cash-=w.cost;p.angle=angle;p.power=power;const before=state.players.map(q=>({...q})),groundBefore=state.ground.slice(),hit=trace(state,actor,angle,power),blasts=[[hit.x,hit.y,w.radius,w.damage]];if(!hit.miss)hit.path.push([hit.x,hit.y,hit.path.at(-1)?.[2]||0]);if(weapon==='cluster'&&!hit.miss)blasts.push([hit.x-34,hit.y,27,24],[hit.x+34,hit.y,27,24]);const damages=[0,0];for(const [x,y,r,d] of blasts){if(hit.miss)continue;for(let i=0;i<2;i++){const target=state.players[i],distance=Math.hypot(target.x-x,target.y-y),amount=Math.round(d*clamp(1-distance/(r+20),0,1)),actual=Math.min(target.hp,amount);target.hp-=actual;damages[i]+=actual;if(i!==actor){if(state.mode!=='basic')p.score+=actual*10;p.cash+=actual*5;}}carve(state.ground,x,y,r,state.seed,state.round);}const motion=hit.miss?[]:settleTanks(state),impactPlayers=state.players.map(q=>({...q})),impactGround=state.ground.slice();let ended=state.players.some(q=>q.hp<=0)||state.shots>=39;state.shots++;let roundWinner=null,roundScores=null;if(ended){const alive=state.players.map(q=>q.hp>0);for(let i=0;i<2;i++){const q=state.players[i];if(alive[i]){q.score+=state.mode==='basic'?500:150;q.cash+=300;}if(alive[i]&&!alive[1-i]){q.kills++;q.score+=state.mode==='basic'?1000:500;q.cash+=500;}}roundScores=state.players.map((q,i)=>q.score-state.roundStartScores[i]);roundWinner=alive[0]!==alive[1]?(alive[0]?0:1):(state.players[0].hp!==state.players[1].hp?(state.players[0].hp>state.players[1].hp?0:1):(roundScores[0]===roundScores[1]?null:(roundScores[0]>roundScores[1]?0:1)));if(state.round>=state.maxRounds){const metric=i=>state.mode==='greedy'?state.players[i].cash:state.players[i].score;state.winner=metric(0)===metric(1)?(state.players[0].hp>=state.players[1].hp?0:1):(metric(0)>metric(1)?0:1);}else{state.round++;state.shots=0;state.roundStartScores=state.players.map(q=>q.score);state.ground=terrain((state.seed+state.round*7919)>>>0);state.wind=Math.round((((state.seed+state.round*17)%19)-9)*.8);for(let i=0;i<2;i++){const q=state.players[i];q.hp=100;q.x=i?855:105;q.y=groundAt(state.ground,q.x)-15;q.vx=q.vy=q.rotation=q.angularVelocity=0;}}}state.turn=1-actor;state.last={actor,angle,power,weapon,hit,damages,ended,beforeRound,windBefore,before,groundBefore,impactPlayers,impactGround,roundWinner,roundScores,motion,scoreGains:state.players.map((q,i)=>q.score-before[i].score)};return state.last;}
export function bestShot(state,player){let best=null;const enemy=state.players[1-player];for(let angle=20;angle<=80;angle+=2)for(let power=30;power<=100;power+=2){const t=trace(state,player,angle,power),distance=Math.hypot(enemy.x-t.x,enemy.y-t.y);if(!best||distance<best.distance)best={angle,power,distance};}return {angle:clamp(best.angle+Math.round((Math.random()-.5)*6),5,85),power:clamp(best.power+Math.round((Math.random()-.5)*6),10,100),weapon:'shell'};}
